# Let me manually check the transformations
inputs = ['iadc', 'fyekcj', 'dagxe', 'ai', 'hhhdud']
outputs = ['iaac', 'fyekcj', 'aagxe', 'ai', 'hhhkca']

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")
    if inp != outp:
        # Find differences
        for j, (in_char, out_char) in enumerate(zip(inp, outp)):
            if in_char != out_char:
                print(f"  Position {j}: '{in_char}' -> '{out_char}'")
        # Check if one string is longer
        if len(inp) != len(outp):
            print(f"  Length difference: {len(inp)} -> {len(outp)}")
    else:
        print("  No change")
    print()

